  Theorem free_exit : forall (two : bool) s msF mo regs mem p (A cap : Z) (status : word) (pending : list byte) junk,
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xa4190) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    getr regs 2 = Z_to_bv 64 (bv_unsigned sp0 - 128) -> getr regs 4 = Z_to_bv 64 ATP -> getr regs 8 = status -> getr regs 9 = Z_to_bv 64 A ->
    bv_unsigned status < 256 ->
    as_RHEAP H s [(p, A, cap)] mem -> rw_cells bsegs mem A [CB (Z.to_nat cap) junk] -> addressable mem A cap ->
    as_Cf H cap <= as_AL H s ->
    xstat two mem -> ostate pending mem -> (pending <> [] -> two = true) ->     (* [comment removed for export] *)
    fd_lookup (m_fds mo) (Z_to_bv 64 1) = Some (FdChannel (Z_to_bv 64 1)) ->
